def is_good(g, sample_points):
    # Check Condition 3
    if g(1) != 1:
        return False

    import itertools
    for a, b in itertools.permutations(sample_points, 2):
        # Condition 1
        if g(a * b) == 0:
            if not (g(a) == 0 or g(b) == 0):
                return False
        # Condition 2
        if g(a * b) != 0:
            lhs = (g(a) - g(b)) / (a - b)
            rhs = (g(a) * g(b)) / g(a * b)
            if abs(lhs - rhs) > 1e-9:
                return False
    return True

# Test g(x) = x
g1 = lambda x: x
# Test g(x) = 1 if x=1 else 0
g2 = lambda x: 1 if x == 1 else 0
# Test g(x) = x if x in {1, 2} else 0
# Wait, {1, 2} is not a subgroup. Let's try H = {1, 2, 4, 8, ...}
# But H must be a subgroup, so it must contain 1/2, 1/4, ...
# Let's try a subgroup H = {2^k : k in Z}
def g_H(x):
    import math
    # Check if x is a power of 2
    if x <= 0: return 0
    try:
        k = math.log2(x)
        if abs(k - round(k)) < 1e-9:
            return x
        else:
            return 0
    except:
        return 0

sample_points = [1, 2, 4, 0.5, 3, 5, 6, 1.5]
print(f"g1 is good: {is_good(g1, sample_points)}")
print(f"g2 is good: {is_good(g2, sample_points)}")
print(f"g_H is good: {is_good(g_H, sample_points)}")
